#include <bits/stdc++.h>
using namespace std;

int func(int n) {
    if (n == 0) return 0;
    int val = 1;
    while (val <= n / 2) {
        val *= 2;
    }
    return 1 + func(n - val);
}

int main() {
    int n;
    cin >> n;
    cout << func(n);
    return 0;
}

